"""Operational helpers that call system tools."""
import subprocess


def echo_status(host: str) -> str:
    # Enforce that the host string contains only allowed characters for a simple echo command.
    # This prevents shell injection by ensuring no shell metacharacters are present.
    if not re.match(r'^[a-zA-Z0-9.-]+$', host):
        raise ValueError("Invalid characters in host name")
    # Use subprocess.run without shell=True to prevent shell injection.
    result = subprocess.run(["echo checking " + host], capture_output=True, text=True, timeout=5)
    return result.stdout.strip()

